import{_ as r,c as t,o as s,ag as e}from"./chunks/framework._xRlcm3f.js";const g=JSON.parse('{"title":"WordPress.com 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/wordpress-wordpressdotcom.md","filePath":"platforms/wordpress-wordpressdotcom.md","lastUpdated":1790228279000}'),d={name:"platforms/wordpress-wordpressdotcom.md"};function a(l,o,c,i,n,p){return s(),t("div",null,[...o[0]||(o[0]=[e('<h1 id="wordpress-com-配置指南" tabindex="-1">WordPress.com 配置指南 <a class="header-anchor" href="#wordpress-com-配置指南" aria-label="Permalink to &quot;WordPress.com 配置指南&quot;">​</a></h1><p>通过 <strong>MetaWeblog XML-RPC</strong> 协议把思源笔记发布到 <strong>WordPress.com</strong> 站点。</p><blockquote><p><strong>前提：需要代理。</strong> WordPress.com 在部分网络环境下无法直接访问，请自备代理并保持开启；<strong>先用浏览器确认能打开你的站点</strong>，再回来验证与发布。这是网络环境限制，不是插件配置问题。</p></blockquote><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个 <strong>WordPress.com</strong> 站点（如 <code>yoursite.wordpress.com</code>）。</li><li>WordPress.com 的<strong>登录用户名与登录密码</strong>（MetaWeblog 按账号密码鉴权，不使用 Token）。</li><li>站点已开启 XML-RPC 接口（WordPress 默认提供 <code>/xmlrpc.php</code>）。</li><li><strong>能正常打开该站点的网络环境（代理）</strong>——见上方前提说明。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>站点首页</td><td>你的 WordPress.com 站点地址，如 <code>https://yoursite.wordpress.com</code></td></tr><tr><td>API 地址</td><td>MetaWeblog API 地址，默认由站点地址推导（WordPress 通常为首页下的 <code>/xmlrpc.php</code>），核对无误后一般无需修改</td></tr><tr><td>用户名</td><td>WordPress.com 的登录用户名</td></tr><tr><td>密码</td><td>WordPress.com 的登录密码</td></tr><tr><td>查看文章链接</td><td>查看链接模板，默认 <code>/?p=[postid]</code>，与 WordPress.com 的默认文章地址一致</td></tr><tr><td>发布格式</td><td>正文提交格式，默认 HTML，保持默认即可</td></tr><tr><td>图床</td><td>按需选择「当前平台」「PicGo 强烈推荐」或「不使用」</td></tr></tbody></table><blockquote><p>WordPress.com 的文章直接发布到站点，不涉及目录概念，因此配置页<strong>没有「发布目录」行</strong>；文章<strong>分类</strong>可在本页选择（验证后下拉列出站点已有分类，可多选）。</p></blockquote><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 站点连通性与账号校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选 WordPress.com → 发布。文章提交到站点。</li><li>「查看文章」按 <code>/?p=[postid]</code> 打开；若站点启用了自定义永久链接，请在「查看规则」里改成实际形态。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>验证失败或提示账号错误</strong>：确认用户名是 WordPress.com 的登录用户名、密码是登录密码（不使用 Token）；再确认站点地址与 API 地址正确。</li><li><strong>提示网络错误、连不上站点</strong>：先确认当前网络能正常打开你的 WordPress.com 站点（用浏览器访问首页即可）。插件按宿主自身的网络通道访问站点，与浏览器能否打开保持一致；若所在网络无法访问该站点，请先解决网络可达性再回来验证。</li><li><strong>为什么没有「发布目录」</strong>：WordPress.com 的文章直接发布到站点，不涉及目录概念。文章<strong>分类</strong>可在本页选择，验证后下拉列出站点已有分类并支持多选。</li><li><strong>图片要怎么发布</strong>：按需选择图床。「当前平台」随文章提交到站点媒体库；「PicGo 强烈推荐」先在上层设置里配置好 PicGo；「不使用」则按原图地址引用。</li><li><strong>查看链接打不开</strong>：链接按 <code>/?p=[postid]</code> 拼出；若站点启用了自定义永久链接，请在「查看规则」里改成实际形态。</li><li><strong>更新与删除</strong>：点「更新」会覆盖站点上的同一篇文章；「删除」会移除该文章。</li></ul>',12)])])}const h=r(d,[["render",a]]);export{g as __pageData,h as default};
